# Zoogi Roll Awaken FX (launch ring / shock chain / void portal) asset build. Re-runnable.
# Imports the procedural textures in Scripts/kfx/finale/tex (generated by gen_tex.py, no third-party art) and builds
#   /Game/VFX/AwakenFX/{T_ZAFX_*, M_ZAFX_* masters, MI_ZAFX_* instances, NS_ZAFX_Embers, NS_ZAFX_Sparks}
# used by AZoogiAwakenFX (Source/ZoogiRoll/Private/ZoogiAwakenFX.cpp).
import unreal, os
EAL = unreal.EditorAssetLibrary
MEL = unreal.MaterialEditingLibrary
AT = unreal.AssetToolsHelpers.get_asset_tools()
L = unreal.ZoogiFXLibrary
ROOT = '/Game/VFX/AwakenFX'
HERE = os.path.dirname(os.path.abspath(__file__))
TPL = '/Niagara/DefaultAssets/Templates/Emitters/'
unreal.AssetRegistryHelpers.get_asset_registry().scan_paths_synchronous(['/Niagara', '/Game/VFX'], True)
def log(s): unreal.log('ZAFX ' + s)
LC = unreal.LinearColor

# ------------------------------------------------------------ textures
def import_textures():
    tasks = []
    d = os.path.join(HERE, 'tex')
    for f in sorted(os.listdir(d)):
        if not f.endswith('.png'): continue
        t = unreal.AssetImportTask()
        t.set_editor_property('filename', os.path.join(d, f)); t.set_editor_property('destination_path', ROOT + '/Textures')
        t.set_editor_property('automated', True); t.set_editor_property('replace_existing', True); t.set_editor_property('save', False)
        tasks.append(t)
    AT.import_asset_tasks(tasks)
    for t in tasks:
        n = os.path.splitext(os.path.basename(t.get_editor_property('filename')))[0]
        a = unreal.load_asset(ROOT + '/Textures/' + n)
        if not a: log('texture import FAILED ' + n); continue
        a.set_editor_property('srgb', False)  # channel-packed masks (ring / splat / portal / bolt): linear
        a.set_editor_property('compression_settings', unreal.TextureCompressionSettings.TC_DEFAULT)
        EAL.save_loaded_asset(a)
    log('textures %d' % len(tasks))
def T(n): return unreal.load_asset(ROOT + '/Textures/' + n)

# ------------------------------------------------------------ material helpers
def fresh(name, cls=unreal.Material, factory=None, folder='/Materials'):
    p = ROOT + folder + '/' + name
    if EAL.does_asset_exist(p): EAL.delete_asset(p)
    return AT.create_asset(name, ROOT + folder, cls, factory or unreal.MaterialFactoryNew())
def E(m, cls, x=0, y=0): return MEL.create_material_expression(m, cls, x, y)
def C(a, ao, b, bi):
    if ao == 'RGB' and isinstance(a, (unreal.MaterialExpressionVectorParameter, unreal.MaterialExpressionVertexColor)): ao = ''  # default output is RGB
    if not MEL.connect_material_expressions(a, ao, b, bi): log('CONNECT FAILED %s.%s -> %s.%s' % (a.get_class().get_name(), ao, b.get_class().get_name(), bi))
def S(m, name, v):
    e = E(m, unreal.MaterialExpressionScalarParameter); e.set_editor_property('parameter_name', name); e.set_editor_property('default_value', v); return e
def V(m, name, v):
    e = E(m, unreal.MaterialExpressionVectorParameter); e.set_editor_property('parameter_name', name); e.set_editor_property('default_value', v); return e
def K(m, v):
    e = E(m, unreal.MaterialExpressionConstant); e.set_editor_property('r', v); return e
def TX(m, name, uv, default=ROOT + '/Textures/T_ZAFX_White'):  # linear white (sampler type Linear Color)
    e = E(m, unreal.MaterialExpressionTextureSampleParameter2D); e.set_editor_property('parameter_name', name)
    e.set_editor_property('texture', unreal.load_asset(default)); e.set_editor_property('sampler_type', unreal.MaterialSamplerType.SAMPLERTYPE_LINEAR_COLOR)
    if uv is not None: C(uv, '', e, 'UVs')
    return e
def O(m, cls, a, b, ao='', bo=''):
    e = E(m, cls)
    if a is not None: C(a, ao, e, 'A')
    if b is not None: C(b, bo, e, 'B')
    return e
def F(m, cls, a, ao=''):
    e = E(m, cls); C(a, ao, e, ''); return e
MUL, ADD, SUB, DIV = unreal.MaterialExpressionMultiply, unreal.MaterialExpressionAdd, unreal.MaterialExpressionSubtract, unreal.MaterialExpressionDivide
SAT = unreal.MaterialExpressionSaturate
def mul(m, a, b, ao='', bo=''): return O(m, MUL, a, b, ao, bo)
def add(m, a, b, ao='', bo=''): return O(m, ADD, a, b, ao, bo)
def sub(m, a, b, ao='', bo=''): return O(m, SUB, a, b, ao, bo)
def app(m, a, b):
    e = E(m, unreal.MaterialExpressionAppendVector); C(a, '', e, 'A'); C(b, '', e, 'B'); return e
def dot(m, a, b, ao='', bo=''):
    e = E(m, unreal.MaterialExpressionDotProduct); C(a, ao, e, 'A'); C(b, bo, e, 'B'); return e
def mask(m, a, r=False, g=False, b=False, al=False):
    e = E(m, unreal.MaterialExpressionComponentMask); C(a, '', e, '')
    e.set_editor_property('r', r); e.set_editor_property('g', g); e.set_editor_property('b', b); e.set_editor_property('a', al); return e
def tc(m, idx=0):
    e = E(m, unreal.MaterialExpressionTextureCoordinate); e.set_editor_property('coordinate_index', idx); return e
def usage(m):
    for p in ('used_with_niagara_sprites', 'used_with_niagara_mesh_particles', 'used_with_niagara_ribbons'):
        try: m.set_editor_property(p, True)
        except Exception as ex: log('usage %s %s' % (p, ex))
def finish(m):
    MEL.recompile_material(m); EAL.save_loaded_asset(m); return m
def uvchain(m):
    # Spin rotation about the card centre, then Tile, + Time*Pan, + UV1.x*RandOffset (per-quad random from the procedural mesh)
    uv0 = tc(m, 0)
    tm = E(m, unreal.MaterialExpressionTime)
    rot = E(m, unreal.MaterialExpressionRotator); rot.set_editor_property('speed', 1.0)
    C(uv0, '', rot, 'Coordinate'); C(mul(m, tm, S(m, 'Spin', 0.0)), '', rot, 'Time')
    tile = app(m, S(m, 'TileU', 1.0), S(m, 'TileV', 1.0))
    pan = mul(m, tm, app(m, S(m, 'PanU', 0.0), S(m, 'PanV', 0.0)))
    rnd = mul(m, mask(m, tc(m, 1), r=True), S(m, 'RandOffset', 0.0))
    uv = add(m, add(m, mul(m, rot, tile), pan), rnd)
    return uv0, rot, uv
def shape(m, uv0, uv):
    # a = saturate(dot(Tex.rgb, Chan) * Mask.r * Contrast - Bias); returns (tex, a)
    t = TX(m, 'Tex', uv)
    ch = dot(m, t, V(m, 'Chan', LC(1, 0, 0, 0)), 'RGB', 'RGB')
    mk = TX(m, 'MaskTex', uv0)
    a = F(m, SAT, sub(m, mul(m, mul(m, ch, mk, '', 'R'), S(m, 'Contrast', 1.0)), S(m, 'Bias', 0.0)))
    return t, a

def build_add():
    # additive unlit: (a*Tint*Glow + Tex.g*CoreGlow) * Fade * VertexColor   (glow cards, flames, bolts, sparks)
    m = fresh('M_ZAFX_Add')
    m.set_editor_property('blend_mode', unreal.BlendMode.BLEND_ADDITIVE); m.set_editor_property('shading_model', unreal.MaterialShadingModel.MSM_UNLIT)
    m.set_editor_property('two_sided', True); usage(m)
    uv0, rot, uv = uvchain(m)
    t, a = shape(m, uv0, uv)
    vc = E(m, unreal.MaterialExpressionVertexColor)
    col = mul(m, mul(m, a, V(m, 'Tint', LC(1, 1, 1, 1)), '', 'RGB'), S(m, 'Glow', 1.0))
    core = mul(m, mul(m, t, S(m, 'CoreGlow', 0.0), 'G'), V(m, 'CoreTint', LC(1, 1, 1, 1)), '', 'RGB')
    em = mul(m, mul(m, mul(m, add(m, col, core), S(m, 'Fade', 1.0)), vc, '', 'RGB'), vc, '', 'A')
    MEL.connect_material_property(em, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    return finish(m)

def build_rock():
    # opaque lit stone for the Void rock + debris: BaseColor = Tint * (0.55 + 0.9 * noise), rough, violet fresnel rim
    m = fresh('M_ZAFX_Rock')
    uv = mul(m, tc(m, 0), K(m, 2.0))
    t = TX(m, 'Tex', uv)
    bc = mul(m, add(m, mul(m, t, K(m, 0.9), 'R'), K(m, 0.55)), V(m, 'Tint', LC(0.1, 0.1, 0.1, 1)), '', 'RGB')
    MEL.connect_material_property(bc, '', unreal.MaterialProperty.MP_BASE_COLOR)
    MEL.connect_material_property(K(m, 0.85), '', unreal.MaterialProperty.MP_ROUGHNESS)
    fr = E(m, unreal.MaterialExpressionFresnel)
    MEL.connect_material_property(mul(m, fr, V(m, 'RimColor', LC(0, 0, 0, 1)), '', 'RGB'), '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    return finish(m)

def build_portal():
    # translucent unlit portal interior: dark violet void, slowly rotating stars + nebula, glowing inner edge; disc from PortalRim.G
    m = fresh('M_ZAFX_Portal')
    m.set_editor_property('blend_mode', unreal.BlendMode.BLEND_TRANSLUCENT); m.set_editor_property('shading_model', unreal.MaterialShadingModel.MSM_UNLIT)
    m.set_editor_property('two_sided', True)
    uv0 = tc(m, 0); tm = E(m, unreal.MaterialExpressionTime)
    rim = TX(m, 'RimTex', uv0)
    rot = E(m, unreal.MaterialExpressionRotator); rot.set_editor_property('speed', 1.0)
    C(uv0, '', rot, 'Coordinate'); C(mul(m, tm, S(m, 'StarSpin', 0.06)), '', rot, 'Time')
    st = TX(m, 'StarTex', mul(m, rot, S(m, 'StarTile', 1.6)))
    rot2 = E(m, unreal.MaterialExpressionRotator); rot2.set_editor_property('speed', 1.0)
    C(uv0, '', rot2, 'Coordinate'); C(mul(m, tm, S(m, 'NebSpin', -0.03)), '', rot2, 'Time')
    nb = TX(m, 'NebTex', mul(m, rot2, S(m, 'NebTile', 0.9)))
    stars = mul(m, mul(m, st, S(m, 'StarGlow', 3.0), 'R'), V(m, 'StarTint', LC(0.85, 0.8, 1.0, 1)), '', 'RGB')
    neb = mul(m, mul(m, nb, S(m, 'NebGlow', 0.5), 'G'), V(m, 'NebTint', LC(0.3, 0.08, 0.6, 1)), '', 'RGB')
    edge = mul(m, mul(m, rim, S(m, 'EdgeGlow', 1.0), 'R'), V(m, 'EdgeTint', LC(0.55, 0.18, 1.0, 1)), '', 'RGB')
    em = mul(m, add(m, add(m, add(m, V(m, 'DarkTint', LC(0.01, 0.004, 0.025, 1)), stars, 'RGB'), neb), edge), S(m, 'Fade', 1.0))
    MEL.connect_material_property(em, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    opac = mul(m, mul(m, F(m, SAT, mul(m, rim, S(m, 'InsideSharp', 1.4), 'G')), S(m, 'Opacity', 0.97)), S(m, 'Fade', 1.0))
    MEL.connect_material_property(opac, '', unreal.MaterialProperty.MP_OPACITY)
    return finish(m)

def build_decal(name, darken):
    # deferred decal. R = emissive glow, G = reveal order (sweep), B = scorch darkening.
    m = fresh(name)
    m.set_editor_property('material_domain', unreal.MaterialDomain.MD_DEFERRED_DECAL)
    m.set_editor_property('blend_mode', unreal.BlendMode.BLEND_TRANSLUCENT)
    uv0, rot, uv = uvchain(m)
    t = TX(m, 'Tex', uv)
    ch = dot(m, t, V(m, 'Chan', LC(1, 0, 0, 0)), 'RGB', 'RGB')
    g = mask(m, t, g=True)
    rvs = F(m, SAT, mul(m, sub(m, S(m, 'Reveal', 1.0), g), S(m, 'RevealSharp', 30.0)))
    one = K(m, 1.0)
    rv = E(m, unreal.MaterialExpressionLinearInterpolate); C(one, '', rv, 'A'); C(rvs, '', rv, 'B'); C(S(m, 'UseReveal', 0.0), '', rv, 'Alpha')
    fade = S(m, 'Fade', 1.0)
    glowA = F(m, SAT, sub(m, mul(m, ch, S(m, 'Contrast', 1.0)), S(m, 'Bias', 0.0)))
    em = mul(m, mul(m, mul(m, mul(m, glowA, V(m, 'Tint', LC(1, 0.5, 0.15, 1)), '', 'RGB'), S(m, 'Glow', 1.0)), rv), fade)
    MEL.connect_material_property(em, '', unreal.MaterialProperty.MP_EMISSIVE_COLOR)
    if darken:
        b = mask(m, t, b=True)
        op_ = F(m, SAT, add(m, mul(m, b, S(m, 'Darken', 0.85)), mul(m, glowA, S(m, 'EmisOpac', 1.0))))
        MEL.connect_material_property(mul(m, mul(m, op_, rv), fade), '', unreal.MaterialProperty.MP_OPACITY)
        MEL.connect_material_property(V(m, 'BaseTint', LC(0.02, 0.016, 0.014, 1)), '', unreal.MaterialProperty.MP_BASE_COLOR)
        MEL.connect_material_property(K(m, 0.95), '', unreal.MaterialProperty.MP_ROUGHNESS)
    else:
        MEL.connect_material_property(mul(m, mul(m, glowA, rv), fade), '', unreal.MaterialProperty.MP_OPACITY)
    return finish(m)

MASTER = {}
def mi(name, master, params):
    a = fresh(name, unreal.MaterialInstanceConstant, unreal.MaterialInstanceConstantFactoryNew())
    MEL.set_material_instance_parent(a, MASTER[master])
    for k, v in params.items():
        if isinstance(v, unreal.Texture): MEL.set_material_instance_texture_parameter_value(a, k, v)
        elif isinstance(v, unreal.LinearColor): MEL.set_material_instance_vector_parameter_value(a, k, v)
        else: MEL.set_material_instance_scalar_parameter_value(a, k, float(v))
    EAL.save_loaded_asset(a); return a

ORANGE = LC(1.0, 0.24, 0.03, 1); FLAME = LC(1.0, 0.22, 0.025, 1)  # round 12: deep orange, not yellow
VIOLET = LC(0.62, 0.30, 1.0, 1); BOLT = LC(0.45, 0.24, 1.0, 1)
R1, G1, B1 = LC(1, 0, 0, 0), LC(0, 1, 0, 0), LC(0, 0, 1, 0)

def build_mis():
    # --- launch ring (Effect4 orange)
    mi('MI_ZAFX_RingDecal', 'Decal', {'Tex': T('T_ZAFX_Ring'), 'Chan': R1, 'Tint': ORANGE, 'Glow': 1.7, 'Darken': 0.85, 'EmisOpac': 1.0,
                                       'BaseTint': LC(0.025, 0.018, 0.012, 1), 'UseReveal': 1.0, 'RevealSharp': 25.0, 'Contrast': 1.2})
    mi('MI_ZAFX_RingInner', 'DecalGlow', {'Tex': T('T_ZAFX_RingInner'), 'Chan': R1, 'Tint': LC(1.0, 0.26, 0.04, 1), 'Glow': 1.0})  # warm orange glow inside the ring
    mi('MI_ZAFX_RingFloor', 'Decal', {'Tex': T('T_ZAFX_RingFloor'), 'Chan': R1, 'Tint': LC(1.0, 0.28, 0.04, 1), 'Glow': 1.0, 'Darken': 0.95, 'EmisOpac': 0.6,
                                       'BaseTint': LC(0.012, 0.007, 0.005, 1), 'UseReveal': 0.0})
    mi('MI_ZAFX_Flame', 'Add', {'Tex': T('T_ZAFX_Noise'), 'MaskTex': T('T_ZAFX_Flame'), 'Chan': R1, 'TileU': 1.0, 'TileV': 0.6, 'PanV': 1.3,
                                 'RandOffset': 7.31, 'Contrast': 2.4, 'Bias': 0.35, 'Tint': FLAME, 'Glow': 1.9, 'CoreGlow': 0.0})
    mi('MI_ZAFX_Ember', 'Add', {'Tex': T('T_ZAFX_Dot'), 'Chan': R1, 'Tint': LC(1.0, 0.55, 0.18, 1), 'Glow': 6.0})
    # --- shock chain (Effect25 purple)
    mi('MI_ZAFX_Bolt', 'Add', {'Tex': T('T_ZAFX_Bolt'), 'Chan': R1, 'Tint': BOLT, 'Glow': 3.2, 'CoreGlow': 2.2, 'CoreTint': LC(0.85, 0.8, 1.0, 1)})
    mi('MI_ZAFX_Orb', 'Add', {'Tex': T('T_ZAFX_Glow'), 'Chan': R1, 'Tint': VIOLET, 'Glow': 2.5})
    mi('MI_ZAFX_Flash', 'Add', {'Tex': T('T_ZAFX_Glow'), 'Chan': R1, 'Tint': LC(0.75, 0.62, 1.0, 1), 'Glow': 6.0})
    mi('MI_ZAFX_Splat', 'Decal', {'Tex': T('T_ZAFX_Splat'), 'Chan': R1, 'Tint': LC(0.6, 0.35, 1.0, 1), 'Glow': 1.6, 'Darken': 1.8, 'EmisOpac': 1.0,
                                   'BaseTint': LC(0.004, 0.003, 0.006, 1), 'UseReveal': 0.0})
    # round 12: small soft bright lavender wash at each strike point (no darkening, no pale haze over the area)
    mi('MI_ZAFX_ShockGlow', 'DecalGlow', {'Tex': T('T_ZAFX_Glow'), 'Chan': R1, 'Tint': LC(0.72, 0.55, 1.0, 1), 'Glow': 1.5, 'UseReveal': 0.0})
    mi('MI_ZAFX_Spark', 'Add', {'Tex': T('T_ZAFX_Dot'), 'Chan': R1, 'Tint': LC(0.72, 0.52, 1.0, 1), 'Glow': 9.0})
    # --- void portal (Effect5 violet)
    mi('MI_ZAFX_PortalInner', 'Portal', {'RimTex': T('T_ZAFX_PortalRim'), 'StarTex': T('T_ZAFX_Stars'), 'NebTex': T('T_ZAFX_Stars'), 'StarTile': 2.2, 'StarGlow': 3.4})  # denser starfield
    mi('MI_ZAFX_PortalRim', 'Add', {'Tex': T('T_ZAFX_PortalRim'), 'Chan': R1, 'Spin': 0.35, 'Tint': LC(0.62, 0.26, 1.0, 1), 'Glow': 1.35, 'Contrast': 1.0})  # thicker, softer rim
    mi('MI_ZAFX_PortalGlow', 'Add', {'Tex': T('T_ZAFX_Glow'), 'Chan': R1, 'Tint': LC(0.50, 0.16, 1.0, 1), 'Glow': 0.07})
    mi('MI_ZAFX_Mote', 'Add', {'Tex': T('T_ZAFX_Dot'), 'Chan': R1, 'Tint': LC(0.8, 0.55, 1.0, 1), 'Glow': 5.0})
    # round 12: broad soft magenta-violet wash, no darkening (the old Darken/BaseTint read as a dark blob)
    mi('MI_ZAFX_Spill', 'DecalGlow', {'Tex': T('T_ZAFX_Glow'), 'Chan': R1, 'Tint': LC(0.85, 0.22, 1.0, 1), 'Glow': 1.6, 'Contrast': 0.9, 'UseReveal': 0.0})
    mi('MI_ZAFX_Rock', 'Rock', {'Tex': T('T_ZAFX_Noise'), 'Tint': LC(0.045, 0.040, 0.050, 1), 'RimColor': LC(0.30, 0.10, 0.75, 1)})  # darker boulder

# ------------------------------------------------------------ Niagara
def system(name, tpl, mat, cfg):
    p = ROOT + '/' + name
    if EAL.does_asset_exist(p): EAL.delete_asset(p)
    s = AT.create_asset(name, ROOT, unreal.NiagaraSystem, unreal.NiagaraSystemFactoryNew())
    en = 'K' + name.split('_')[-1]
    if not L.add_emitter_from_asset(s, unreal.load_asset(TPL + tpl), en): log('add emitter FAILED ' + name); return
    L.set_emitter_local_space(s, en, False)
    L.set_niagara_float(s, en, 'EmitterState.MaxDistance', 1000000.0)
    L.set_emitter_render(s, en, mat, None)
    for k, v in cfg.items():
        if isinstance(v, int) and not isinstance(v, bool): n = L.set_niagara_int(s, en, k, v)
        elif isinstance(v, unreal.LinearColor): n = L.set_niagara_color(s, en, k, v)
        elif isinstance(v, unreal.Vector): n = L.set_niagara_vector(s, en, k, v)
        else: n = L.set_niagara_float(s, en, k, float(v))
        if not n: log('%s: input not found %s' % (name, k))
    log('%s compile: %s' % (name, L.compile_report(s)))
    EAL.save_loaded_asset(s)

def build_niagara():
    def M(n): return unreal.load_asset(ROOT + '/Materials/' + n)
    # embers drifting up off the launch ring (component scale = ring radius / 100 -> sphere radius 100 hits the ring line)
    system('NS_ZAFX_Embers', 'Fountain', M('MI_ZAFX_Ember'), {
        'SpawnRate.SpawnRate': 40.0, 'InitializeParticle.Lifetime Min': 0.9, 'InitializeParticle.Lifetime Max': 2.0,
        'Uniform Sprite Size Min': 2.5, 'Uniform Sprite Size Max': 5.5, 'InitializeParticle.Color': LC(1.0, 0.55, 0.2, 1),
        'RandomRangeFloat.Minimum': 25.0, 'RandomRangeFloat.Maximum': 90.0, 'AddVelocity.Cone Angle': 35.0,
        'GravityForce.Gravity': unreal.Vector(0, 0, 25), 'Drag.Drag': 0.6,
        'ShapeLocation.Sphere Radius': 100.0, 'ShapeLocation.Non Uniform Scale': unreal.Vector(1, 1, 0.02), 'ShapeLocation.Sphere Surface Distribution': 1.0})
    # violet spark burst where a bolt strikes / the rock lands
    system('NS_ZAFX_Sparks', 'OmnidirectionalBurst', M('MI_ZAFX_Spark'), {
        'SpawnBurst_Instantaneous.Spawn Count': 36, 'InitializeParticle.Lifetime Min': 0.2, 'InitializeParticle.Lifetime Max': 0.65,
        'Uniform Sprite Size Min': 2.0, 'Uniform Sprite Size Max': 4.5, 'InitializeParticle.Color': LC(0.75, 0.55, 1.0, 1),
        'RandomRangeFloat.Minimum': 180.0, 'RandomRangeFloat.Maximum': 650.0, 'GravityForce.Gravity': unreal.Vector(0, 0, -980), 'Drag.Drag': 2.0,
        'ShapeLocation.Sphere Radius': 8.0})

import_textures()
MASTER['Add'] = build_add()
MASTER['Portal'] = build_portal()
MASTER['Rock'] = build_rock()
MASTER['Decal'] = build_decal('M_ZAFX_Decal', True)
MASTER['DecalGlow'] = build_decal('M_ZAFX_DecalGlow', False)
build_mis()
build_niagara()
log('done')
